mapper.select:
SELECT t1.id , t2.* , m.word as gender_name FROM t_member t1 INNER JOIN t_member_detail t2 ON t2.member_id = t1.member_id AND t2.delete_flg = 0 LEFT JOIN m_common m ON m.id = t2.gender AND m.group_id = 1 AND m.delete_flg = 0 WHERE t1.delete_flg = 0
AND t1.id = #{id}
AND t2.name LIKE CONCAT('%', #{name}, '%');
;

mapper.insert:
INSERT INTO
  t_member_detail (
    email
    , name
    , birthday
    , gender
    , phone_no
    , postcode
    , delete_flg
    , create_date
    , update_date
  )
VALUES (
  #{email}
  , #{name}
  , #{birthday}
  , #{gender}
  , #{phone_no}
  , #{postcode}
  , 0
  , NOW()
  , NOW()
);
